  function syncBoxPromotion(){const enabled=productHasBox.checked&&productBoxHasPromotion.checked,price=form.elements.boxSalePrice,label=form.elements.boxPromotionLabel,original=Number(form.elements.boxPrice.value);productBoxPromotionFields.hidden=!enabled;price.disabled=!enabled;label.disabled=!enabled;price.required=enabled;if(original>0)price.max=Math.max(.01,original-.01).toFixed(2);}
  function validateProductImage(file){if(!file)return true;const allowed=['image/jpeg','image/png','image/webp','image/avif'];if(!allowed.includes(file.type)){toast('Escolha uma imagem JPG, PNG, WEBP ou AVIF.');return false}if(file.size>5*1024*1024){toast('A imagem deve ter no máximo 5 MB.');return false}return true}
  productImagePreview.addEventListener('error',()=>{productImagePreview.hidden=true;productImageEmpty.hidden=false;productImageEmpty.textContent='Prévia indisponível'});
  productImageFile.addEventListener('change',()=>{const file=productImageFile.files[0];if(!file)return;if(!validateProductImage(file)){productImageFile.value='';return}productImageStatus.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`;const reader=new FileReader();reader.onload=()=>showProductImage(reader.result);reader.readAsDataURL(file)});
  productBoxImageFile.addEventListener('change',()=>{const file=productBoxImageFile.files[0];if(!file)return;if(!validateProductImage(file)){productBoxImageFile.value='';return}productBoxImageStatus.textContent=`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`;const reader=new FileReader();reader.onload=()=>showBoxImage(reader.result);reader.readAsDataURL(file)});
  form.elements.image.addEventListener('change',()=>{if(!productImageFile.files.length)showProductImage(form.elements.image.value.trim())});
  form.elements.boxImage.addEventListener('change',()=>{if(!productBoxImageFile.files.length)showBoxImage(form.elements.boxImage.value.trim())});
  function kitCandidates(){const editing=form.elements.id.value;return products.filter(product=>product.id!==editing&&!(Array.isArray(product.kit_items)&&product.kit_items.length))}
  function kitNameFromSelection(){return kitItems.map(item=>products.find(product=>product.id===item.productId)?.name||item.name).filter(Boolean).join(' + ')}
  function syncKitName(){if(productIsKit.checked){const name=kitNameFromSelection();form.elements.name.readOnly=kitItems.length>0;if(name)form.elements.name.value=name}}
  function renderKitItems(){
    productKitFields.hidden=!productIsKit.checked;
    if(!productIsKit.checked){productKitItems.replaceChildren();return;}
    const candidates=kitCandidates();
    productKitItems.innerHTML=kitItems.length?kitItems.map((item,index)=>`<div class="product-kit-item"><label>Produto<select data-kit-product="${index}"><option value="">Descrever componente</option>${candidates.map(product=>`<option value="${escapeHtml(product.id)}" ${product.id===item.productId?'selected':''}>${escapeHtml(product.name)}</option>`).join('')}</select><input data-kit-name="${index}" value="${escapeHtml(item.name||'')}" placeholder="Nome do componente" ${item.productId?'hidden':'required'}></label><label>Quantidade<input data-kit-quantity="${index}" type="number" min="1" max="100" step="1" value="${item.quantity??''}" placeholder="Não informada"></label><button type="button" class="mini-button cancel" data-remove-kit-item="${index}">Remover</button></div>`).join(''):'<p class="product-kit-empty">Adicione pelo menos dois produtos ao combo.</p>';
    syncKitName();
  }
  function addKitItem(){const used=new Set(kitItems.map(item=>item.productId)),candidate=kitCandidates().find(product=>!used.has(product.id));if(!candidate){toast('Não há outro produto disponível para adicionar ao combo.');return}kitItems.push({productId:candidate.id,quantity:1});renderKitItems()}
  productIsKit.addEventListener('change',()=>{if(productIsKit.checked&&!kitItems.length){addKitItem();addKitItem()}else renderKitItems()});
  productHasPromotion.addEventListener('change',()=>{syncProductPromotion();if(productHasPromotion.checked&&!form.elements.salePrice.value&&Number(form.elements.price.value)>0)form.elements.salePrice.value=(Number(form.elements.price.value)*.9).toFixed(2);});
  productBoxHasPromotion.addEventListener('change',()=>{syncBoxPromotion();if(productBoxHasPromotion.checked&&!form.elements.boxSalePrice.value&&Number(form.elements.boxPrice.value)>0)form.elements.boxSalePrice.value=(Number(form.elements.boxPrice.value)*.9).toFixed(2);});
  form.elements.price.addEventListener('input',syncProductPromotion);
  form.elements.boxPrice.addEventListener('input',syncBoxPromotion);
  productHasBox.addEventListener('change',()=>{productBoxFields.hidden=!productHasBox.checked;for(const input of [form.elements.boxUnits,form.elements.boxPrice])input.required=productHasBox.checked;if(!productHasBox.checked)productBoxHasPromotion.checked=false;syncBoxPromotion()});
  document.querySelector('#addKitItem').addEventListener('click',addKitItem);
  productKitItems.addEventListener('change',e=>{const productIndex=e.target.dataset.kitProduct,quantityIndex=e.target.dataset.kitQuantity;if(productIndex!==undefined){const item=kitItems[Number(productIndex)];item.productId=e.target.value;item.name=products.find(p=>p.id===item.productId)?.name||item.name||'';renderKitItems();}if(quantityIndex!==undefined)kitItems[Number(quantityIndex)].quantity=e.target.value?Math.max(1,Math.min(100,Number(e.target.value)||1)):null;if(e.target.dataset.kitName!==undefined)kitItems[Number(e.target.dataset.kitName)].name=e.target.value.trim();syncKitName();});
  productKitItems.addEventListener('click',e=>{const button=e.target.closest('[data-remove-kit-item]');if(!button)return;kitItems.splice(Number(button.dataset.removeKitItem),1);renderKitItems()});
  function openProduct(p={id:'',name:'',description:'',price:'',category:'',image:'',available:true,featured:false,kit_items:[],box_option:null,sale_price:null,promotion_label:null}){form.reset();document.querySelector('#standaloneBoxUnitsField').hidden=!(p.box_units||p.category===StoreAPI.boxCategoryName);form.elements.standaloneBoxUnits.required=false;form.elements.standaloneBoxUnits.value=p.box_units||'';Object.keys(p).forEach(k=>{if(form.elements[k]){if(form.elements[k].type==='checkbox')form.elements[k].checked=Boolean(p[k]);else form.elements[k].value=p[k]??''}});if(!productCategorySelect.value&&categories.length)productCategorySelect.value=categories[0];const sale=Number(p.sale_price);productHasPromotion.checked=Number.isFinite(sale)&&sale>0&&sale<Number(p.price);form.elements.salePrice.value=productHasPromotion.checked?sale.toFixed(2):'';form.elements.promotionLabel.value=p.promotion_label||'';syncProductPromotion();kitItems=Array.isArray(p.kit_items)?p.kit_items.map(item=>({productId:products.some(p=>p.id===item.productId)?item.productId:'',name:item.name||'',quantity:item.quantity??null})):[];productIsKit.checked=kitItems.length>0;renderKitItems();productHasBox.checked=Boolean(p.box_option);productBoxFields.hidden=!productHasBox.checked;form.elements.boxUnits.required=productHasBox.checked;form.elements.boxPrice.required=productHasBox.checked;form.elements.boxUnits.value=p.box_option?.units||'';form.elements.boxPrice.value=p.box_option?.price||'';const boxSale=Number(p.box_option?.sale_price);productBoxHasPromotion.checked=Number.isFinite(boxSale)&&boxSale>0&&boxSale<Number(p.box_option?.price);form.elements.boxSalePrice.value=productBoxHasPromotion.checked?boxSale.toFixed(2):'';form.elements.boxPromotionLabel.value=p.box_option?.promotion_label||'';syncBoxPromotion();form.elements.boxImage.value=p.box_option?.image||'';productImageFile.value='';productImageStatus.textContent='Nenhum arquivo selecionado';productImageEmpty.textContent='Imagem';showProductImage(p.image||'');productBoxImageFile.value='';productBoxImageStatus.textContent='Nenhum arquivo selecionado';productBoxImageEmpty.textContent='Foto do fardo';showBoxImage(p.box_option?.image||'');document.querySelector('#dialogTitle').textContent=p.id?'Editar produto':'Novo produto';editorMode(productIsKit.checked||p.product_type==='combo'?'kit':'product');dialog.showModal()}
  document.querySelector('#addProduct').addEventListener('click',async()=>{if(!categories.length){toast('Adicione uma categoria antes de cadastrar o produto.','warning');categoryDialog.showModal();return}openProduct()});
  document.querySelector('#adminProducts').addEventListener('click',async e=>{
    const editButton=e.target.closest('[data-edit]'),deleteButton=e.target.closest('[data-delete]'),stockButton=e.target.closest('[data-stock]');
    const edit=editButton?.dataset.edit,del=deleteButton?.dataset.delete,stock=stockButton?.dataset.stock;
    if(edit)openProduct(products.find(p=>p.id===edit));
    if(stock){const current=products.find(product=>product.id===stock);if(!current)return;const updated={...current,id:current.id,name:current.name,description:current.description,price:Number(current.price),sale_price:current.sale_price??null,promotion_label:current.promotion_label??null,category:current.category,image:current.image,available:!current.available,featured:Boolean(current.featured),kit_items:Array.isArray(current.kit_items)?current.kit_items:[],box_option:current.box_option||null};try{await StoreAPI.saveProduct(updated);products=products.map(product=>product.id===stock?updated:product);renderProducts();toast(updated.available?'Produto reativado no catálogo':'Produto marcado como em falta',updated.available?'success':'warning')}catch(err){toast(err.message||'Não foi possível alterar o estoque.','danger')}}
    if(del){
      const product=products.find(item=>item.id===del);if(!product)return;
      deleteButton.disabled=true;
      try{
        const confirmed=await window.AdminFeedback.confirm({tone:'warning',title:'Excluir produto?',message:`${product.name} será removido do catálogo. Esta ação não pode ser desfeita.`,confirmLabel:'Excluir produto',cancelLabel:'Cancelar'});
        if(!confirmed)return;
        await StoreAPI.deleteProduct(del);products=await StoreAPI.getProducts(true);renderProducts();renderCategories();toast('Produto excluído','success');
      }catch(err){toast(err.message||'Não foi possível excluir o produto.','danger')}
      finally{if(deleteButton.isConnected)deleteButton.disabled=false;}
    }
  });
  document.querySelector('#saveProduct').addEventListener('click',async()=>{if(productEditorMode==='box'){await saveBox();return;}if(!form.reportValidity())return;const f=new FormData(form),file=productImageFile.files[0],boxFile=productBoxImageFile.files[0],button=document.querySelector('#saveProduct');if((file&&!validateProductImage(file))||(boxFile&&!validateProductImage(boxFile)))return;if(productIsKit.checked){const ids=kitItems.map(item=>item.productId).filter(Boolean);if(kitItems.length<2){toast('Adicione pelo menos dois produtos ao combo.');return}if(new Set(ids).size!==ids.length){toast('Cada produto deve aparecer apenas uma vez no combo. Ajuste a quantidade quando necessário.');return}}let image=f.get('image').trim(),boxImage=f.get('boxImage').trim();if(!file&&!image){toast('Selecione uma imagem ou informe um caminho.');return}if(productHasBox.checked&&!boxFile&&!boxImage){toast('Selecione uma foto própria para o fardo.');return}if(productHasBox.checked&&!boxFile&&boxImage===image){toast('A foto do fardo deve ser diferente da foto do produto por unidade.');return}button.disabled=true;button.textContent=file||boxFile?'Enviando imagens...':'Salvando...';try{if(file){image=await StoreAPI.uploadProductImage(file);productImageStatus.textContent='Upload concluído'}if(boxFile){boxImage=await StoreAPI.uploadProductImage(boxFile);productBoxImageStatus.textContent='Upload concluído'}const savedKitItems=productIsKit.checked?kitItems.map(item=>{const component=products.find(product=>product.id===item.productId);return{productId:item.productId,name:component?.name||item.name||'Produto',quantity:item.quantity??null}}):[],product={...products.find(item=>item.id===f.get('id')),id:f.get('id')||crypto.randomUUID(),name:savedKitItems.length?savedKitItems.map(item=>item.name).join(' + '):f.get('name').trim(),description:f.get('description').trim(),price:Number(f.get('price')),sale_price:productHasPromotion.checked?Number(f.get('salePrice')):null,promotion_label:productHasPromotion.checked?(f.get('promotionLabel').trim()||null):null,category:f.get('category').trim(),product_type:productEditorMode==='kit'?'combo':(products.find(p=>p.id===f.get('id'))?.product_type==='box'?'box':'product'),image,available:form.available.checked,featured:form.featured.checked,kit_items:savedKitItems,box_option:productHasBox.checked?{units:Number(f.get('boxUnits')),price:Number(f.get('boxPrice')),image:boxImage,sale_price:productBoxHasPromotion.checked?Number(f.get('boxSalePrice')):null,promotion_label:productBoxHasPromotion.checked?(f.get('boxPromotionLabel').trim()||null):null}:null};if(productHasPromotion.checked&&(!Number.isFinite(product.sale_price)||product.sale_price<=0||product.sale_price>=product.price)){toast('O preço promocional deve ser maior que zero e menor que o original.','warning');return;}if(productBoxHasPromotion.checked&&(!Number.isFinite(product.box_option.sale_price)||product.box_option.sale_price<=0||product.box_option.sale_price>=product.box_option.price)){toast('O preço promocional do fardo deve ser maior que zero e menor que o preço normal do fardo.','warning');return;}if(product.box_units||product.category===StoreAPI.boxCategoryName){product.box_units=form.elements.standaloneBoxUnits.value?Number(form.elements.standaloneBoxUnits.value):null;product.category=StoreAPI.boxCategoryName;}await StoreAPI.saveProduct(product);products=await StoreAPI.getProducts(true);renderProducts();renderCategories(product.category);renderDashboard();dialog.close();toast(product.box_option?'Produto e fardo salvos':product.kit_items.length?'Combo salvo':'Produto salvo')}catch(err){toast(err.message||'Não foi possível salvar o produto.')}finally{button.disabled=false;button.textContent='Salvar'}});
  window.addEventListener('zeus:catalog-imported',()=>loadAll().catch(err=>toast(err.message,'danger')));
