  (async()=>{try{const authenticated=await StoreAPI.isAuthenticated();showAuthenticatedState(authenticated);if(authenticated)await loadAll()}catch(err){showAuthenticatedState(false);toast(err.message||'Não foi possível verificar a sessão.')}})();
